package main
import("context";"database/sql";"encoding/json";"fmt";"time";"math";"fanapi/internal/billing";"fanapi/internal/model";"github.com/spf13/viper";_ "github.com/lib/pq")
func main(){v:=viper.New();v.SetConfigFile("/app/config.yaml");must(v.ReadInConfig());d,e:=sql.Open("postgres",fmt.Sprintf("host=%s port=%d user=%s password=%s dbname=%s sslmode=%s connect_timeout=10",v.GetString("db.host"),v.GetInt("db.port"),v.GetString("db.user"),v.GetString("db.password"),v.GetString("db.dbname"),v.GetString("db.sslmode")));must(e);defer d.Close();ctx,cancel:=context.WithTimeout(context.Background(),20*time.Second);defer cancel()
rows,e:=d.QueryContext(ctx,`SELECT id,model,protocol,billing_config FROM channels WHERE billing_type='token' AND billing_config->>'gpt_context_pricing'='true' ORDER BY id`);must(e);defer rows.Close();count:=0
for rows.Next(){ch:=model.Channel{BillingType:"token"};var raw []byte;must(rows.Scan(&ch.ID,&ch.Model,&ch.Protocol,&raw));must(json.Unmarshal(raw,&ch.BillingConfig));for _,n:=range []int64{272000,272001,300000}{u:=map[string]interface{}{"prompt_tokens":n,"completion_tokens":int64(1000),"cache_read_tokens":int64(200000)};resp:=map[string]interface{}{"usage":u};sale,e:=billing.CalcActualCost(&ch,nil,resp);must(e);cost,e:=billing.CalcActualUpstreamCost(&ch,nil,resp);must(e);rate:=func(key string)float64{switch x:=ch.BillingConfig[key].(type){case float64:return x};return 0};for _,kind:=range []string{"price","cost"}{in,out:=rate("input_"+kind+"_per_1m_tokens"),rate("output_"+kind+"_per_1m_tokens");read:=rate("cache_read_"+kind+"_per_1m_tokens");if _,ok:=ch.BillingConfig["cache_read_"+kind+"_per_1m_tokens"];!ok{read=math.Ceil(in*.1)};if n>272000{in*=2;out=math.Ceil(out*1.5);read*=2};want:=int64(math.Ceil(float64(n-200000)*in/1e6)+math.Ceil(200000*read/1e6)+math.Ceil(1000*out/1e6));got:=sale;if kind=="cost"{got=cost};if got!=want{panic(fmt.Sprintf("channel %d %s threshold %d got %d want %d",ch.ID,kind,n,got,want))}}
fmt.Printf("CHANNEL %d %s INPUT %d SALE %d COST %d VERIFIED\n",ch.ID,ch.Model,n,sale,cost)};count++};must(rows.Err());if count==0{panic("no dynamic channels")};fmt.Printf("VERIFIED_CHANNELS %d\n",count)
}
func must(e error){if e!=nil{panic(e)}}
